22	const sum = (amounts: number[]): number =>
23	  amounts.reduce((total, amount) => total + amount, 0);
24	
25	const PROCESSING_FEE = 5;
26	
27	// Binary floating point makes exact multiples land a hair off (100 * 1.1 + 5 =
28	// 115.00000000000001); snap to cent precision so only genuine fractions round up.
29	const roundUpInMHPCOsFavour = (amount: number): number =>
30	  Math.ceil(Number(amount.toFixed(6)));
31	
32	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
33	  sword: 100,
34	  amulet: 60,
35	  staff: 80,
36	  potion: 40,
37	  rune: 25,
38	};
39	
40	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
41	
42	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
43	
44	const quote = (step: QuoteStep): number => {
45	  const policyBasePremium = sum(step.items.map(basePremiumOf));
46	  const firstInsuranceSurcharge =
47	    policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
48	
49	  return roundUpInMHPCOsFavour(
50	    policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE,
51	  );
52	};
53	
54	export const runScenario = (scenario: Scenario): ScenarioResults => {
55	  return { results: scenario.steps.map((step) => ({ premium: quote(step) })) };
56	};
